SELECT iq.id, u.email AS user_email, iq.title, iq.content, iq.status, iq.answer, iq.answered_at, iq.created_at FROM inquiries iq JOIN users u ON u.id = iq.user_id
iq.status = #{status}
ORDER BY iq.created_at DESC, iq.id DESC

